<?php require '_layout.php'; $pdo=db(); $edit=isset($_GET['id']); $u=['id'=>'','name'=>'','email'=>'','role'=>'editor','active'=>1]; if($edit&&$pdo){$q=$pdo->prepare('SELECT id,name,email,role,active FROM users WHERE id=?');$q->execute([(int)$_GET['id']]);$u=$q->fetch(PDO::FETCH_ASSOC)?:$u;} admin_header($edit?'Chỉnh sửa người dùng':'Thêm người dùng','users'); ?><section class="form-page"><div class="form-heading"><div><a class="back" href="users.php">← Quay lại người dùng</a><h2><?=$edit?'Chỉnh sửa người dùng':'Thêm người dùng'?></h2><p><?=$edit?'Để trống mật khẩu nếu không cần thay đổi.':'Tạo tài khoản truy cập khu vực Admin.'?></p></div></div><form class="product-form user-form" method="post" action="user-save.php"><input type="hidden" name="id" value="<?=$u['id']?>"><div class="form-main"><section class="form-card"><h3>Thông tin tài khoản</h3><div class="field"><label>Họ tên *</label><input required name="name" value="<?=htmlspecialchars($u['name'])?>"></div><div class="field"><label>Email *</label><input required type="email" name="email" value="<?=htmlspecialchars($u['email'])?>"></div><div class="field"><label>Mật khẩu <?=$edit?'mới':''?> <?=$edit?'':'*'?></label><input <?=$edit?'':'required'?> minlength="8" type="password" name="password" autocomplete="new-password"><small>Tối thiểu 8 ký tự.</small></div></section></div><aside class="form-side"><section class="form-card"><h3>Quyền truy cập</h3><div class="field"><label>Vai trò</label><select name="role"><option value="editor" <?=$u['role']==='editor'?'selected':''?>>Biên tập viên</option><option value="admin" <?=$u['role']==='admin'?'selected':''?>>Quản trị viên</option></select></div><label class="switch-row"><input type="checkbox" name="active" value="1" <?=$u['active']?'checked':''?>><span></span><div><b>Tài khoản hoạt động</b><small>Có thể đăng nhập Admin</small></div></label></section><button class="admin-button save"><?=$edit?'Lưu thay đổi':'Tạo người dùng'?></button><a class="cancel" href="users.php">